 if(module==='petty'){const pending=sum(values('petty').filter(p=>!p.reimbursed).map(p=>p.amount));h='<div class="sw-head">'+btn('Registrar comprobante','petty')+btn('Configurar fondo autorizado','settings')+'</div><div class="sw-stats">'+stat('Fondo autorizado',money(d.fund))+stat('Pendiente de reintegro',money(pending))+stat('Disponible en el fondo',money(d.fund-pending))+'</div><section class="sw-panel">'+table(['Fecha','Comprobante','Concepto','Responsable','Monto','Reintegro','Acciones'],items('petty').map(r=>{let p=r.payload;return[esc(p.date),esc(p.reference),esc(p.concept),esc(p.responsible),money(p.amount),p.reimbursed?'Reintegrado':'Pendiente',edit(r)];}))+'<p class="sw-note">Cada comprobante entra una sola vez en las salidas y en Administración. No lo registre de nuevo en Flujo de caja. Marcarlo reintegrado repone el fondo mediante un traslado interno; no crea otro gasto. El saldo inicial consolidado debe incluir la caja chica.</p></section>';}
 if(module==='budget')h=budgetView();
 if(module==='statements'){const r=items('statement')[0],p=r?.payload;h='<div class="sw-head">'+btn(p?'Editar estado del período':'Registrar estado financiero','statement')+'</div><section class="sw-panel" aria-labelledby="sw-compare-title"><h2 id="sw-compare-title">Comparar dos años</h2><p>El año seleccionado arriba es <strong>'+year+'</strong>. Escriba el año con el que quiere compararlo y pulse <strong>Ver comparación</strong>. Ambos deben tener un cierre al 31 de diciembre.</p><div class="sw-head"><label for="sw-base">Comparar '+year+' con el año <input id="sw-base" type="number" min="1900" max="2200" value="'+(base!==year?base:year-1)+'"></label><button type="button" class="sw-btn" id="sw-compare">Ver comparación</button></div><div id="sw-comparison" aria-live="polite"></div></section><section class="sw-panel">'+(p?'<h2>Corte al '+esc(p.date)+'</h2>'+table(['Cuenta','Monto'],statementRows(p).map(([a,n])=>[esc(a),money(n)]))+'<p class="sw-note">'+esc(p.note)+'</p><p>'+financialComment(p)+'</p>':'<p>Registre las cifras de los estados financieros. Este apartado no toma los ingresos contables del flujo de caja.</p>')+'</section>';}
 if(module==='assets'){h='<div class="sw-head">'+btn('Registrar activo','asset')+'</div><div class="sw-stats">'+stat('Activos registrados',String(items('asset').length))+stat('Costo histórico',money(sum(values('asset').map(p=>p.cost))))+stat('Valor en libros',money(sum(values('asset').map(p=>p.cost-p.depreciation))))+'</div><section class="sw-panel">'+table(['Código / activo','Adquisición','Ubicación / responsable','Costo','Depreciación acumulada','Valor en libros','Acciones'],items('asset').map(r=>{const p=r.payload;return[esc(p.code)+' · '+esc(p.name)+'<br>'+esc(p.category)+' · '+esc(p.state),esc(p.date)+'<br>Vida útil: '+p.life+' años',esc(p.location)+'<br>'+esc(p.responsible),money(p.cost),money(p.depreciation),money(p.cost-p.depreciation),edit(r)];}))+'<p class="sw-note">Registre la depreciación acumulada al cierre del período según su auxiliar contable. No se calcula automáticamente. Los activos de cada año son un corte del auxiliar de ese año.</p></section>';}
 if(module==='workplan'){h=workplanView();}
